#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_sources_cover_entity_types_and_only_rabbit_is_dynamic() {
        assert_eq!(
            ENTITY_SOUND_SOURCES.len(),
            crate::entity_types::VANILLA_ENTITY_TYPES.len()
        );
        for entry in crate::entity_types::VANILLA_ENTITY_TYPES {
            assert_eq!(
                vanilla_entity_sound_source_kind(entry.id)
                    == Some(VanillaEntitySoundSourceKind::Dynamic),
                entry.resource_id == "minecraft:rabbit"
            );
        }
        assert_eq!(vanilla_entity_sound_source_kind(-1), None);
        assert_eq!(
            vanilla_entity_sound_source_kind(ENTITY_SOUND_SOURCES.len() as i32),
            None
        );
    }
}
